// The people's side held equal to the Python gateway's: the checks, the rows it writes, and the operations driven through
// Gateway.freeze_session, end_session, hold_triggers, release_triggers, human_answer and the inbox's handlers (generated by
// tools/gen_gateway_registry.py into testdata/people.json). The differences that are deliberate (docs/admin/go-gateway.md) are
// listed in the tests that meet them.

func peopleFixture(t testing.TB) map[string]json.RawMessage {
	var f map[string]json.RawMessage
	readJSON(t, "testdata/people.json", &f)
	return f
}

func into(t testing.TB, raw json.RawMessage, v any) {
	t.Helper()
	d := json.NewDecoder(strings.NewReader(string(raw)))
	d.UseNumber()
	if err := d.Decode(v); err != nil {
		t.Fatal(err)
	}
}

// pyValue is a JSON value as Python's json.loads gives it, for the checks that take whatever a caller sent: a number is a float64
// unless it is whole, and Python's True is a bool.
func pyValue(v any) any {
	if n, ok := v.(json.Number); ok {
		if i, err := n.Int64(); err == nil {
			return i
		}
		f, _ := n.Float64()
		return f
	}
	return v
}

type outcome struct {
	OK    any `json:"ok"`
	Error *struct {
		Rule    string `json:"rule"`
		Message string `json:"message"`
		Status  int    `json:"status"`
	} `json:"error"`
}

func sameError(t *testing.T, label string, want *struct {
	Rule    string `json:"rule"`
	Message string `json:"message"`
	Status  int    `json:"status"`
}, err error) {
	t.Helper()
	switch e := err.(type) {
	case *dispatch.InboxError:
		if want == nil || want.Rule != e.Rule || want.Message != e.Message || want.Status != e.Status {
			t.Errorf("%s: %+v, Python %+v", label, e, want)
		}
	case *dispatch.ControlError:
		if want == nil || want.Rule != e.Rule || want.Message != e.Message || want.Status != e.Status {
			t.Errorf("%s: %+v, Python %+v", label, e, want)
		}
	case nil:
		if want != nil {
			t.Errorf("%s: no error, Python %+v", label, want)
		}
	default:
		t.Errorf("%s: %v", label, err)
	}
}

func TestInboxChecksEqualPython(t *testing.T) {
	f := peopleFixture(t)
	var qs []struct {
		Question, Options any
		outcome
	}
	into(t, f["check_question"], &qs)
	for _, c := range qs {
		q, o, err := dispatch.CheckQuestion(pyValue(c.Question), pyOpts(c.Options))
		sameError(t, fmt.Sprint("question ", c.Question, c.Options), c.Error, err)
		if c.Error == nil {
			want := c.OK.([]any)
			if q != want[0] || !reflect.DeepEqual(strs(o), strs(want[1])) {
				t.Errorf("%v %v: %q %v, Python %v", c.Question, c.Options, q, o, want)
			}
		}
	}
	reqs := map[string]*dispatch.HumanRequest{
		"options":  {ID: "h-1", Owner: "user:alice", Options: []string{"a", "b"}, CreatedAt: t0, ExpiresAt: t0.Add(time.Hour), Status: "pending"},
		"free":     {ID: "h-2", Owner: "user:alice", CreatedAt: t0, ExpiresAt: t0.Add(time.Hour), Status: "pending"},
		"answered": {ID: "h-3", Owner: "user:alice", CreatedAt: t0, ExpiresAt: t0.Add(time.Hour), Status: "answered", AnsweredBy: ptr("user:bob")},
	}
	var as []struct {
		Request string `json:"request"`
		At      string `json:"at"`
		Answer  any    `json:"answer"`
		outcome
	}
	into(t, f["check_answer"], &as)
	for _, c := range as {
		at, _ := dispatch.ParsePyIso(c.At)
		got, err := dispatch.CheckAnswer(reqs[c.Request], pyValue(c.Answer), at)
		sameError(t, fmt.Sprint("answer ", c.Request, c.At, c.Answer), c.Error, err)
		if c.Error == nil && got != c.OK {
			t.Errorf("%v: %q, Python %v", c.Answer, got, c.OK)
		}
	}
	var may []struct {
		Person string
		Groups []string
		Owner  bool
		Free   bool
	}
	into(t, f["may_answer"], &may)
	group := "group:default/team"
	for _, c := range may {
		gs := map[string]bool{}
		for _, g := range c.Groups {
			gs[g] = true
		}
		if dispatch.MayAnswer(&dispatch.HumanRequest{Owner: "user:alice", Group: &group}, c.Person, gs) != c.Owner ||
			dispatch.MayAnswer(&dispatch.HumanRequest{Owner: "user:alice"}, c.Person, gs) != c.Free {
			t.Errorf("%+v", c)
		}
	}
}

func pyOpts(o any) any {
	if o == nil {
		return nil
	}
	if l, ok := o.([]any); ok {
		out := make([]any, len(l))
		for i, x := range l {
			out[i] = pyValue(x)
		}
		return out
	}
	return pyValue(o)
}

func strs(v any) []string {
	var out []string
	switch x := v.(type) {
	case []string:
		return x
	case []any:
		for _, e := range x {
			out = append(out, fmt.Sprint(e))
		}
	}
	return out
}

func TestControlChecksEqualPython(t *testing.T) {
	f := peopleFixture(t)
	var hs []struct {
		Hours any
		outcome
	}
	into(t, f["check_hours"], &hs)
	for _, c := range hs {
		got, err := dispatch.CheckHours(pyValue(c.Hours))
		// Python's int() also reads a string of non-ASCII digits ("٣" is 3); Go reads only ASCII digits (stricter, documented).
		if s, ok := c.Hours.(string); ok && s == "٣" {
			if err == nil {
				t.Errorf("a non-ASCII digit string was accepted")
			}
			continue
		}
		sameError(t, fmt.Sprint("hours ", c.Hours), c.Error, err)
		if c.Error == nil && json.Number(fmt.Sprint(got)) != c.OK.(json.Number) {
			t.Errorf("%v: %d, Python %v", c.Hours, got, c.OK)
		}
	}
	var rs []struct {
		Reason any
		outcome
	}
	into(t, f["check_reason"], &rs)
	for _, c := range rs {
		got, err := dispatch.CheckReason(pyValue(c.Reason))
		sameError(t, fmt.Sprint("reason ", c.Reason), c.Error, err)
		if c.Error == nil && got != c.OK {
			t.Errorf("%v: %q, Python %v", c.Reason, got, c.OK)
		}
	}
	var ms []struct {
		Person string
		Owner  *string
		Groups []string
		Admins []string
		Ok     bool
	}
	into(t, f["may_manage"], &ms)
	for _, c := range ms {
		gs := map[string]bool{}
		for _, g := range c.Groups {
			gs[g] = true
		}
		if dispatch.MayManage(c.Person, c.Owner, gs, c.Admins) != c.Ok {
			t.Errorf("%+v", c)
		}
	}
}

func TestRowsEqualPython(t *testing.T) {
	f := peopleFixture(t)
	var rows []map[string]any
	into(t, f["inbox_rows"], &rows)
	for _, row := range rows {
		r, err := dispatch.HumanRequestFromRecord(row)
		if err != nil {
			t.Fatal(err)
		}
		if !reflect.DeepEqual(norm(t, r.Record()), norm(t, row)) {
			t.Errorf("a request row Python wrote does not read back whole:\n go  %v\n py  %v", norm(t, r.Record()), norm(t, row))
		}
	}
	var views []struct {
		View map[string]any
		At   string
	}
	into(t, f["inbox_views"], &views)
	for i, v := range views {
		// the views are of (a pending request with options, an answered one, a full one), which the rows are in the order 2, 0, 1
		r, _ := dispatch.HumanRequestFromRecord(rows[[]int{2, 0, 1}[i]])
		at, _ := dispatch.ParsePyIso(v.At)
		if got := r.View(at); !reflect.DeepEqual(norm(t, got), norm(t, v.View)) {
			t.Errorf("view %d:\n go  %v\n py  %v", i, norm(t, got), norm(t, v.View))
		}
	}
	var holds []map[string]any
	into(t, f["holds"], &holds)
	for _, h := range holds {
		got, err := dispatch.HoldFromRecord(h)
		if err != nil || !reflect.DeepEqual(norm(t, got.View()), norm(t, h)) {
			t.Errorf("%v %v", got, h)
		}
	}
	var evs []map[string]any
	into(t, f["events"], &evs)
	rec, err := dispatch.EventFromSummary(map[string]any{"id": "e1", "app": "Gate-API", "routingKey": "gate-api.pipelinerun.finished", "receivedAt": "2026-09-26T11:59:00Z", "type": "t",
		"subject": map[string]any{"id": "pr-1", "content": map[string]any{"outcome": "failure", "n": 3}}},
		[]map[string]any{{"agent": "triage-agent", "result": "launched", "session": "s-1", "run": "r-1", "via": "stream", "extra": 1}, {"agent": "", "result": "x"}, {"result": "no agent"}}, t0, "glidepath")
	if err != nil || !reflect.DeepEqual(norm(t, rec.View()), norm(t, evs[0])) {
		t.Errorf("%v\n go  %v\n py  %v", err, norm(t, rec.View()), norm(t, evs[0]))
	}
}

// peopleAuth is the Python fixture's authenticator: the token is the principal id, user:... is a person, anything else a workload.
type peopleAuth struct{}

func (peopleAuth) Authenticate(_ context.Context, token string) (*dispatch.Principal, error) {
	if token == "nobody" {
		return nil, &core.AuthError{Msg: "token not accepted"}
	}
	kind := "workload"
	if strings.HasPrefix(token, "user:") {
		kind = "user"
	}
	return &dispatch.Principal{ID: token, Kind: kind, TierCeiling: 1}, nil
}

func pythonRig(t *testing.T, initial []session.Record) *peopleRig {
	p := newPeopleRig(t, withPersist(newPersist(initial...)))
	p.g.Auth = peopleAuth{}
	p.dir["user:grace"] = []string{"group:default/team-platform"}
	st, _ := session.NewStore(ctx, p.persist)
	p.g.Store, p.store = st, st
	return p
}

func peopleRecords(p *peopleRig) []map[string]any {
	out := []map[string]any{}
	for _, rec := range p.records() {
		out = append(out, rec)
	}
	return out
}

func pyRecords(t testing.TB, raw []map[string]any) []map[string]any {
	out := []map[string]any{}
	for _, r := range raw {
		out = append(out, norm(t, r).(map[string]any))
	}
	return sorted(out)
}

func TestPersonOperationsEqualPython(t *testing.T) {
	f := peopleFixture(t)
	var initial []session.Record
	into(t, f["initial_sessions"], &initial)
	var ops []struct {
		Op         string
		Caller     string
		OnBehalfOf *string `json:"on_behalf_of"`
		Result     map[string]any
		Error      *struct {
			Rule    string `json:"rule"`
			Message string `json:"message"`
			Status  int    `json:"status"`
		}
		Sessions map[string]json.RawMessage
		Records  []map[string]any
		Holds    []map[string]any
		Inbox    []map[string]any
	}
	into(t, f["operations"], &ops)
	if len(ops) < 60 {
		t.Fatalf("%d operations", len(ops))
	}
	compared := 0
	for _, c := range ops {
		p := pythonRig(t, initial)
		on := ""
		if c.OnBehalfOf != nil {
			on = *c.OnBehalfOf
		}
		var out map[string]any
		var err error
		switch c.Op {
		case "freeze":
			out, err = p.g.FreezeSession(ctx, c.Caller, "s-0000a1", "it opens bad PRs", on)
		case "end":
			out, err = p.g.EndSession(ctx, c.Caller, "s-0000a1", "enough", on)
		case "hold":
			out, err = p.g.HoldTriggers(ctx, c.Caller, "triage-agent", "storm", json.Number("2"), on)
		case "release":
			_ = p.holds.Put(ctx, &dispatch.Hold{Agent: "triage-agent", By: "user:x", Reason: "r", Since: t0, Until: t0.Add(time.Hour)})
			out, err = p.g.ReleaseTriggers(ctx, c.Caller, "triage-agent", on)
		case "answer":
			_ = p.inbox.Add(ctx, &dispatch.HumanRequest{ID: "h-000000000001", TaskID: "t-0000a1", Session: "s-0000a1", Agent: "orchestrator", Owner: "user:alice",
				Group: ptr("group:default/team-platform"), Question: "q?", CreatedAt: t0, ExpiresAt: t0.Add(time.Hour), Status: "pending"})
			out, err = p.g.HumanAnswer(ctx, c.Caller, "h-000000000001", "yes", on)
		}
		label := fmt.Sprintf("%s by %s for %v", c.Op, c.Caller, c.OnBehalfOf)
		if on == "user:" {
			// Deliberate: a delegate that names an empty person ("user:") is refused outright (400); Python goes on to ask whether a
			// person with no name may manage the agent, which an admin glob such as "user:*" would say yes to.
			if ctlRule(err) != "CT-PERSON" && ctlRule(err) != "HR-PERSON" || ctlStatus(err) != 400 {
				t.Errorf("%s: %v", label, err)
			}
			continue
		}
		sameError(t, label, c.Error, err)
		if c.Error == nil {
			// audit_seq is the core's: the fake takes a different count than Python's recorder, so compare the rest
			delete(out, "audit_seq")
			want := dropEmpty(c.Result, "").(map[string]any)
			delete(want, "audit_seq")
			if !reflect.DeepEqual(norm(t, out), norm(t, want)) {
				t.Errorf("%s:\n go  %v\n py  %v", label, norm(t, out), norm(t, want))
			}
		}
		for sid, raw := range c.Sessions {
			s := p.store.Get(sid)
			s.Lock()
			rec := s.ToRecord()
			s.Unlock()
			rec.DeleteFail = nil
			var want any
			_ = json.Unmarshal(raw, &want)
			if !reflect.DeepEqual(norm(t, rec), dropEmpty(want, "")) {
				t.Errorf("%s: session %s:\n go  %v\n py  %v", label, sid, norm(t, rec), dropEmpty(want, ""))
			}
		}
		if got, want := p.records(), pyRecords(t, c.Records); !reflect.DeepEqual(norm(t, got), norm(t, want)) {
			t.Errorf("%s: records:\n go  %v\n py  %v", label, norm(t, got), norm(t, want))
		}
		var holds []map[string]any
		all, _ := p.holds.All(ctx)
		for _, h := range all {
			holds = append(holds, h.View())
		}
		if len(holds) != len(c.Holds) || (len(holds) > 0 && !reflect.DeepEqual(norm(t, holds), norm(t, c.Holds))) {
			t.Errorf("%s: holds %v, Python %v", label, holds, c.Holds)
		}
		compared++
	}
	t.Logf("%d operations compared", compared)
}

func TestControlSequencesEqualPython(t *testing.T) {
	f := peopleFixture(t)
	var initial []session.Record
	into(t, f["initial_sessions"], &initial)
	type step struct {
		Op      string
		Caller  string
		Session string
		Reason  string
		Result  map[string]any
		Error   *struct {
			Rule    string `json:"rule"`
			Message string `json:"message"`
			Status  int    `json:"status"`
		}
	}
	var seq struct {
		Steps    []step
		Sessions map[string]json.RawMessage
		Records  []map[string]any
	}
	into(t, f["control_sequence"], &seq)
	p := pythonRig(t, initial)
	for _, s := range seq.Steps {
		var out map[string]any
		var err error
		if s.Op == "freeze" {
			out, err = p.g.FreezeSession(ctx, s.Caller, s.Session, s.Reason, "")
		} else {
			out, err = p.g.EndSession(ctx, s.Caller, s.Session, s.Reason, "")
		}
		sameError(t, s.Op+" "+s.Session+" "+s.Reason, s.Error, err)
		if s.Error == nil {
			delete(out, "audit_seq")
			want := dropEmpty(s.Result, "").(map[string]any)
			delete(want, "audit_seq")
			if !reflect.DeepEqual(norm(t, out), norm(t, want)) {
				t.Errorf("%s:\n go  %v\n py  %v", s.Op, norm(t, out), norm(t, want))
			}
		}
	}
	for sid, raw := range seq.Sessions {
		s := p.store.Get(sid)
		s.Lock()
		rec := s.ToRecord()
		s.Unlock()
		rec.DeleteFail = nil
		var want any
		_ = json.Unmarshal(raw, &want)
		if !reflect.DeepEqual(norm(t, rec), dropEmpty(want, "")) {
			t.Errorf("session %s:\n go  %v\n py  %v", sid, norm(t, rec), dropEmpty(want, ""))
		}
	}
	if got, want := p.records(), pyRecords(t, seq.Records); !reflect.DeepEqual(norm(t, got), norm(t, want)) {
		t.Errorf("records:\n go  %v\n py  %v", norm(t, got), norm(t, want))
	}

	var hold struct {
		Steps []struct {
			Hours  any
			Result map[string]any
			Error  *struct {
				Rule    string `json:"rule"`
				Message string `json:"message"`
				Status  int    `json:"status"`
			}
		}
		Records []map[string]any
	}
	into(t, f["hold_sequence"], &hold)
	p = pythonRig(t, initial)
	for i, s := range hold.Steps {
		var out map[string]any
		var err error
		switch {
		case i < 9:
			out, err = p.g.HoldTriggers(ctx, "user:root", "triage-agent", "storm", pyValue(s.Hours), "")
		case i == 9:
			out, err = p.g.HoldTriggers(ctx, "user:root", "no-such-agent", "storm", json.Number("1"), "")
		case i == 10:
			out, err = p.g.HoldTriggers(ctx, "user:root", "triage-agent", "", json.Number("1"), "")
		default:
			out, err = p.g.ReleaseTriggers(ctx, "user:root", "triage-agent", "")
		}
		sameError(t, fmt.Sprint("hold step ", i, s.Hours), s.Error, err)
		if s.Error == nil {
			delete(out, "audit_seq")
			want := dropEmpty(s.Result, "").(map[string]any)
			delete(want, "audit_seq")
			if !reflect.DeepEqual(norm(t, out), norm(t, want)) {
				t.Errorf("hold step %d:\n go  %v\n py  %v", i, norm(t, out), norm(t, want))
			}
		}
	}
	if got, want := p.records(), pyRecords(t, hold.Records); !reflect.DeepEqual(norm(t, got), norm(t, want)) {
		t.Errorf("hold records:\n go  %v\n py  %v", norm(t, got), norm(t, want))
	}
}

var reqIDRe = regexp.MustCompile(`^h-[0-9a-f]{12}$`)

func TestInboxHandlersEqualPython(t *testing.T) {
	f := peopleFixture(t)
	var initial []session.Record
	into(t, f["initial_sessions"], &initial)
	var steps []map[string]any
	into(t, f["inbox_handlers"], &steps)
	p := pythonRig(t, initial)
	s := p.store.Get("s-0000a1")
	h := p.g.Handlers["human.request"]
	get := p.g.Handlers["human.request.get"]
	var firstID string
	flooded := false
	for i, st := range steps {
		switch {
		case st["args"] != nil:
			got, err := h(ctx, s, st["args"].(map[string]any))
			if den, ok := st["denied"].(map[string]any); ok {
				var d *core.Denied
				if !asDenied(err, &d) || d.Rule != den["rule"] || d.Message != den["message"] || d.Hint != den["hint"] {
					t.Errorf("step %d: %v, Python %v", i, err, den)
				}
				continue
			}
			res := got.(map[string]any)
			if !reqIDRe.MatchString(res["request"].(string)) {
				t.Fatalf("step %d: the id %v", i, res["request"])
			}
			firstID = res["request"].(string)
			want := st["result"].(map[string]any)
			for _, k := range []string{"status", "expires_at", "hint"} {
				if res[k] != want[k] {
					t.Errorf("step %d: %s %v, Python %v", i, k, res[k], want[k])
				}
			}
		case st["get"] != nil:
			var arg any
			switch g := st["get"].(type) {
			case string:
				arg = g
				if g == "id" {
					arg = firstID
				}
			default:
				arg = g // a number
			}
			got, err := get(ctx, s, map[string]any{"request": arg})
			if den, ok := st["denied"].(map[string]any); ok {
				var d *core.Denied
				if !asDenied(err, &d) || d.Rule != den["rule"] || d.Message != den["message"] || d.Hint != den["hint"] {
					t.Errorf("step %d: %v, Python %v", i, err, den)
				}
				continue
			}
			view := got.(map[string]any)
			delete(view, "id")
			if !reflect.DeepEqual(norm(t, view), norm(t, st["result"])) {
				t.Errorf("step %d:\n go  %v\n py  %v", i, norm(t, view), norm(t, st["result"]))
			}
		case st["flood"] != nil:
			if !flooded { // Python asked six times: four were taken (five pending in all), the last two refused
				flooded = true
				for j := 0; j < 4; j++ {
					if _, err := h(ctx, s, map[string]any{"question": "flood"}); err != nil {
						t.Fatalf("flood %d: %v", j, err)
					}
				}
			}
			_, err := h(ctx, s, map[string]any{"question": "flood"})
			den := st["flood"].(map[string]any)
			var d *core.Denied
			if !asDenied(err, &d) || d.Rule != den["rule"] || d.Message != den["message"] || d.Hint != den["hint"] {
				t.Errorf("step %d: %v, Python %v", i, err, den)
			}
		}
	}
}

func asDenied(err error, into **core.Denied) bool {
	d, ok := err.(*core.Denied)
	*into = d
	return ok
}
